document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("board-foot-form"),t=document.getElementById("board-foot-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("lumber-thickness").value),o=parseFloat(document.getElementById("lumber-width").value),s=parseFloat(document.getElementById("lumber-length").value),i=parseFloat(document.getElementById("lumber-quantity").value),r=parseFloat(document.getElementById("lumber-type").value),a=parseFloat(document.getElementById("lumber-waste").value);if(n<=0||o<=0||s<=0||i<=0)return t.textContent="Please enter valid measurements.",void 0;const d=n*o*s/12,p=d*i,l=p*(1+a),c=p*r,u=l*r,m=u-c,f=n*o*s*i/144,h=35*f,b=[{name:"1×4×8",thickness:.75,width:3.5,length:8,bf:2.33},{name:"1×6×8",thickness:.75,width:5.5,length:8,bf:3.67},{name:"2×4×8",thickness:1.5,width:3.5,length:8,bf:4.67},{name:"2×6×8",thickness:1.5,width:5.5,length:8,bf:7.33},{name:"2×8×10",thickness:1.5,width:7.25,length:10,bf:9.58},{name:"2×10×12",thickness:1.5,width:9.25,length:12,bf:15.42}];let $=b[0],g=Math.abs(d-$.bf);b.forEach(e=>{const t=Math.abs(d-e.bf);t<g&&(g=t,$=e)});const v=s*i,F=o*s*i/144;let w="";w=r<=6?"Construction grade suitable for framing, general building":r<=15?"Select grade hardwood suitable for furniture, cabinetry":"Premium grade suitable for fine furniture, musical instruments",t.innerHTML=`\n        <div class="result-section">\n          <h4>Lumber Specifications:</h4>\n          <p>Dimensions: ${n}" × ${o}" × ${s}'</p>\n          <p>Quantity: ${i} pieces</p>\n          <p>Waste factor: ${100*a}%</p>\n        </div>\n        \n        <div class="result-board-feet">\n          <h4>Board Foot Calculations:</h4>\n          <p><strong>Per piece: ${d.toFixed(2)} board feet</strong></p>\n          <p><strong>Total: ${p.toFixed(2)} board feet</strong></p>\n          <p><strong>With waste: ${l.toFixed(2)} board feet</strong></p>\n          <p>Formula: (${n} × ${o} × ${s}) ÷ 12 × ${i}</p>\n        </div>\n        \n        <div class="result-measurements">\n          <h4>Alternative Measurements:</h4>\n          <p>Linear feet: ${v} ft (end-to-end length)</p>\n          <p>Surface area: ${F.toFixed(2)} sq ft (one face)</p>\n          <p>Volume: ${f.toFixed(2)} cubic feet</p>\n          <p>Estimated weight: ${h.toFixed(0)} lbs</p>\n        </div>\n        \n        <div class="result-costs">\n          <h4>Cost Breakdown:</h4>\n          <p>Base cost: $${c.toFixed(2)} (${p.toFixed(2)} bd ft @ $${r})</p>\n          <p>Waste allowance: $${m.toFixed(2)}</p>\n          <p><strong>Total cost: $${u.toFixed(2)}</strong></p>\n          <p>Cost per piece: $${(u/i).toFixed(2)}</p>\n          <p>Cost per linear foot: $${(u/v).toFixed(2)}</p>\n        </div>\n        \n        <div class="result-comparison">\n          <h4>Common Size Comparison:</h4>\n          <p>Your lumber: ${d.toFixed(2)} bd ft per piece</p>\n          <p>Closest standard: ${$.name} (${$.bf.toFixed(2)} bd ft)</p>\n          <p>Difference: ${Math.abs(d-$.bf).toFixed(2)} bd ft</p>\n        </div>\n        \n        <div class="result-grade">\n          <h4>Grade Recommendation:</h4>\n          <p>${w}</p>\n          ${r<=6?"<p>💡 Consider kiln-dried lumber for indoor projects</p>":"<p>💡 Ensure proper moisture content for your application</p>"}\n        </div>\n        \n        <div class="result-ordering">\n          <h4>Ordering Information:</h4>\n          <p>Order: ${Math.ceil(l)} board feet</p>\n          <p>Delivery: ${h>500?"Truck delivery recommended":"Can fit in pickup truck"}</p>\n          <p>Storage: Store flat, supported every 2-3 feet</p>\n          <p>Acclimation: 3-7 days in project environment</p>\n        </div>\n        \n        <div class="result-project-tips">\n          <h4>Project Planning:</h4>\n          <p>🔨 Plan cuts to minimize waste</p>\n          <p>📏 Measure twice, cut once</p>\n          <p>🌡️ Allow lumber to acclimate</p>\n          <p>📦 Buy from same lot for consistency</p>\n          <p>🎯 Use best pieces for visible surfaces</p>\n        </div>\n        \n        <div class="result-alternatives">\n          <h4>Cost Alternatives:</h4>\n          <p>Construction grade: $${(4*p).toFixed(0)} (vs $${c.toFixed(0)})</p>\n          <p>Premium hardwood: $${(25*p).toFixed(0)} (vs $${c.toFixed(0)})</p>\n          <p>💰 ${r>10?"Consider":"More expensive than"} engineered alternatives</p>\n        </div>\n        \n        <div class="result-tools">\n          <h4>Tools for Processing:</h4>\n          <p>📐 Measuring: tape measure, square, calipers</p>\n          <p>🪚 Cutting: table saw, miter saw, circular saw</p>\n          <p>✂️ Joining: router, biscuit joiner, pocket screws</p>\n          <p>📝 Planning: cut list, lumber marking system</p>\n        </div>\n      `})});